import numpy as np, torch, model
net=model.load(); neg=model.negatives()
W=torch.tensor(np.load('contrast_c0_blocks.1_k12.npy'),dtype=torch.float32); b=1.0297
def dec(xi,c,delta=None,klo=0,khi=0,thr=0.0):
    x=torch.tensor(xi,dtype=torch.float32); c=torch.tensor(c,dtype=torch.float32)
    with torch.no_grad():
        for k in range(20):
            t=torch.full((x.shape[0],),1-k/20)
            v,a=net.velocity(x,t,c,("blocks.1",),count=False)
            if delta is not None and klo<=k<khi:
                f=((a['blocks.1']@W+b)>thr).float()[:,None]
                v=v+f*torch.tensor(delta)
            x=x-v/20
    return x.numpy()
rng=np.random.default_rng(0)
N=256; rows=[0,1,2]
XI={i:rng.standard_normal((N,2)).astype(np.float32) for i in rows}
xiD=rng.standard_normal((2048,2)).astype(np.float32); cD=rng.random(2048).astype(np.float32)
baseD=dec(xiD,cD)
res=[]
for klo,khi in [(8,13),(10,13),(6,12),(4,14)]:
  for ang in range(0,360,45):
    for mag in [3,6,12]:
      d=mag*np.array([np.cos(np.radians(ang)),np.sin(np.radians(ang))],np.float32)
      r=np.mean([np.mean(model.in_basin(i,dec(XI[i],np.full(N,neg['c'][i],np.float32),d,klo,khi))) for i in rows])
      aD=dec(xiD,cD,d,klo,khi); mv=np.mean(np.linalg.norm(aD-baseD,axis=1)>0.3)
      res.append((round(r,3),round(mv,3),klo,khi,ang,mag))
res.sort()
for x in res[:20]: print(x)
